using System;using System.IO;using System.Text;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 [InitializeOnLoad]public static class PolishMotionAuditV06 {
  const string Key="ZTM_POLISH_MOTION_V06";static GameView view;static RenderTexture target;static int warm,captured,frame0;static double started,next;static bool pressed,spun,bought,closed;static StringBuilder report=new StringBuilder();static List<double> times=new List<double>();
  static string Root=>Directory.GetParent(Application.dataPath).FullName;static string Tag=>SessionState.GetString(Key+"tag","before");
  static PolishMotionAuditV06(){EditorApplication.update+=Tick;}
  public static string Start(string tag){if(EditorApplication.isPlaying)throw new Exception("Own Editor playing");if(tag!="before"&&tag!="after"&&tag!="final")throw new Exception("Comparison tag");if(Directory.Exists(Path.Combine(Root,".tooling","polish-motion-v06-"+tag)))throw new Exception("Immutable frames exist");view=null;warm=captured=0;started=next=0;pressed=spun=bought=closed=false;report.Clear();times.Clear();Environment.SetEnvironmentVariable("ZTM_QA_SAVE_DIR",Path.Combine(Root,".tooling","polish-motion-v06-"+tag,"save"));UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");SessionState.SetString(Key+"tag",tag);SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();return "queued "+tag;}
  static void Check(bool ok,string text){if(!ok)throw new Exception(text);report.AppendLine("PASS "+text);}
  static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying)return;try{if(view==null){view=UnityEngine.Object.FindFirstObjectByType<GameView>();if(view==null)return;target=new RenderTexture(360,720,0,RenderTextureFormat.ARGB32);target.Create();view.GetComponent<UIDocument>().panelSettings.targetTexture=target;var s=new PlayerState{cash=1000,freeSpins=0};for(int i=0;i<7;i++)s.purchased[i]=true;s.fragments[7]=69;s.tutorial.completed=true;s.tutorial.storySeenMask=7;view.SetQaState(s,3);frame0=Time.frameCount;}
   if(++warm<30)return;if(started==0){started=next=EditorApplication.timeSinceStartup;Directory.CreateDirectory(Path.Combine(Root,".tooling","polish-motion-v06-"+Tag,"frames"));}double now=EditorApplication.timeSinceStartup,t=now-started;
   if(t>=.8&&!pressed){view.QaPressedSpin();pressed=true;}
   if(t>=1.05&&!spun){view.QaReleaseSpin();view.QaClick("spin");Check(view.Model.Snapshot.spins==1,"real spin callback commits once");spun=true;}
   if(t>=4&&!bought&&!view.QaSpinning){Check(view.Model.CanBuy(7),"committed spin reaches final purchase");int cash=view.Model.Snapshot.cash;view.QaClick("buy-7");view.QaBuy(7);Check(view.Model.Complete&&view.Model.Snapshot.cash==cash-355,"manual installation debits once");bought=true;}
   if(t>=6&&!closed){view.QaClick("tutorial-next");closed=true;}
   if(now>=next){var old=RenderTexture.active;RenderTexture.active=target;var image=new Texture2D(360,720,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,360,720),0,0);image.Apply();File.WriteAllBytes(Path.Combine(Root,".tooling","polish-motion-v06-"+Tag,"frames",captured.ToString("D4")+".png"),image.EncodeToPNG());UnityEngine.Object.Destroy(image);RenderTexture.active=old;times.Add(t);captured++;next=now+1.0/20;}
   if(!RoomGeometry.IsFree(view.QaFeet))throw new Exception("Feet intersect obstacle");if(t<9)return;Check(Time.frameCount-frame0>100&&captured>100&&bought,"advancing actual frames, whole interaction captured");report.AppendLine("frame0="+frame0+" finalFrame="+Time.frameCount+" captures="+captured+" seconds="+t.ToString("F3"));report.AppendLine("SOURCE Editor rendered target; synthetic UI callbacks, prepared final-task fixture; no physical/OS input");File.WriteAllText(Path.Combine(Root,"Evidence","polish-motion-v06-"+Tag+"-times.json"),JsonUtility.ToJson(new CaptureTimes{seconds=times.ToArray()}));File.WriteAllText(Path.Combine(Root,"Evidence","polish-motion-v06-"+Tag+"-state.json"),JsonUtility.ToJson(view.Model.Snapshot,true));Finish();
  }catch(Exception e){report.AppendLine("FAIL "+e);Debug.LogException(e);Finish();}}
  [Serializable]sealed class CaptureTimes{public double[] seconds;}
  static void Finish(){SessionState.SetBool(Key,false);File.WriteAllText(Path.Combine(Root,"Evidence","polish-motion-v06-"+Tag+"-checks.txt"),report.ToString());if(target!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);target=null;}EditorApplication.ExitPlaymode();}
 }
}
